<?php
/**
 * Add ABSPATH exit guards to Composer-generated files.
 *
 * Runs via Composer's post-autoload-dump event.
 *
 * @package MediaRon_Block_Shortcuts_For_GB
 */

// Prevent direct web access, but allow CLI execution.
if ( ! defined( 'ABSPATH' ) && 'cli' !== PHP_SAPI ) {
	exit; // Exit if accessed directly.
}

$lib_dir      = __DIR__ . '/../lib';
$composer_dir = $lib_dir . '/composer';
$files        = array();

if ( is_file( $lib_dir . '/autoload.php' ) ) {
	$files[] = $lib_dir . '/autoload.php';
}

if ( is_dir( $composer_dir ) ) {
	$composer_files = glob( $composer_dir . '/*.php' );

	if ( false !== $composer_files ) {
		$files = array_merge( $files, $composer_files );
	}
}

if ( empty( $files ) ) {
	echo "No Composer files found in {$lib_dir}\n";
	exit( 1 );
}

$guard = <<<'GUARD'

// Exit if accessed directly.
if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

GUARD;

/**
 * Insert the ABSPATH guard into a PHP string.
 *
 * The guard is placed after the namespace declaration, if one exists;
 * otherwise it is placed immediately after the opening <?php tag.
 * Opening tags that share a line with code (for example "<?php return array("
 * or "<?php return [") are split first so the guard is not inserted inside
 * that statement.
 *
 * @param string $contents Original file contents.
 * @param string $guard    Guard block to insert.
 * @return string|false Modified contents, or false on error.
 */
function mrshortcutsgb_insert_abspath_guard( $contents, $guard ) {
	if ( substr( $contents, 0, 5 ) !== '<?php' ) {
		return false;
	}

	// Remove any existing guard block generated by this script so it can be re-inserted in the correct location.
	$contents = preg_replace( '/\/\/ Exit if accessed directly\.\nif \( ! defined\( \'ABSPATH\' \) \) \{\n\texit;\n\}\n?/', '', $contents );

	$lines = preg_split( '/\r\n|\r|\n/', $contents );

	// Composer return maps such as installed.php keep "<?php return array(" on one line.
	// Inserting after that line puts the guard inside the argument list and fails php -l.
	// Whitespace after the opening tag is required; code is never glued directly to "<?php".
	if ( isset( $lines[0] ) && preg_match( '/^<\?php\s+(\S.*)$/', trim( $lines[0] ), $matches ) ) {
		$lines[0] = '<?php';
		array_splice( $lines, 1, 0, array( $matches[1] ) );
	}

	// Find the namespace declaration, skipping whitespace, comments, and declare() calls.
	$namespace_line   = -1;
	$line_count       = count( $lines );
	$in_block_comment = false;

	for ( $i = 1; $i < $line_count; $i++ ) {
		$line = trim( $lines[ $i ] );

		if ( $in_block_comment ) {
			if ( false !== strpos( $line, '*/' ) ) {
				$in_block_comment = false;
			}
			continue;
		}

		if ( '' === $line ) {
			continue;
		}

		if ( preg_match( '/^\/\//', $line ) ) {
			continue;
		}

		if ( preg_match( '/^\/\*/', $line ) ) {
			$in_block_comment = true;
			if ( false !== strpos( $line, '*/' ) ) {
				$in_block_comment = false;
			}
			continue;
		}

		if ( preg_match( '/^declare\s*\(/i', $line ) ) {
			continue;
		}

		if ( preg_match( '/^namespace\s+/i', $line ) ) {
			$namespace_line = $i;
		}

		break;
	}

	if ( $namespace_line >= 0 ) {
		array_splice( $lines, $namespace_line + 1, 0, explode( "\n", trim( $guard ) ) );
	} else {
		array_splice( $lines, 1, 0, explode( "\n", trim( $guard ) ) );
	}

	return implode( "\n", $lines );
}

$updated = 0;
$skipped = 0;

foreach ( $files as $file ) {
	$contents = file_get_contents( $file );

	if ( false === $contents ) {
		echo "Failed to read {$file}\n";
		continue;
	}

	$new_contents = mrshortcutsgb_insert_abspath_guard( $contents, $guard );

	if ( false === $new_contents ) {
		echo "Skipping {$file}: does not start with <?php\n";
		++$skipped;
		continue;
	}

	if ( $new_contents === $contents ) {
		++$skipped;
		continue;
	}

	$result = file_put_contents( $file, $new_contents, LOCK_EX );

	if ( false === $result ) {
		echo "Failed to write {$file}\n";
		continue;
	}

	echo "Guard added to {$file}\n";
	++$updated;
}

echo "Updated {$updated} file(s), skipped {$skipped} file(s).\n";
